static lv_style_t * get_local_style(lv_obj_t * obj, lv_style_selector_t selector)
{
    uint32_t i;
    for(i = 0; i < obj->style_cnt; i++) {
        if(obj->styles[i].is_local &&
           obj->styles[i].selector == selector) {
            return (lv_style_t *)obj->styles[i].style;
        }
    }

    lv_style_t * local = lv_malloc_zeroed(sizeof(lv_style_t));
    if(local == NULL) return NULL;
    lv_obj_style_t * resized = lv_realloc(obj->styles, (obj->style_cnt + 1) * sizeof(lv_obj_style_t));
    if(resized == NULL) { lv_free(local); return NULL; }
    obj->styles = resized;
    obj->style_cnt++;

    for(i = obj->style_cnt - 1; i > 0 ; i--) {
        /*Copy only normal styles (not local and transition).
         *The new local style will be added as the last local style*/
        if(obj->styles[i - 1].is_local || obj->styles[i - 1].is_trans) break;
        obj->styles[i] = obj->styles[i - 1];
    }

    lv_memzero(&obj->styles[i], sizeof(lv_obj_style_t));
    obj->styles[i].style = local;
    lv_style_init((lv_style_t *)obj->styles[i].style);

    obj->styles[i].is_local = 1;
    obj->styles[i].selector = selector;
    return (lv_style_t *)obj->styles[i].style;
}

